# ─────────────────────────────────────────────────────────────────────────────
# 统一命令行入口与多平台分发
# ─────────────────────────────────────────────────────────────────────────────
AUTO_CONFIRM=0
DEPLOY_MODE=""
PLATFORM_OVERRIDE="auto"
CUSTOM_DIR=""
CUSTOM_VER=""

for _arg in "$@"; do
    case "$_arg" in
        -y|--yes|--silent)
            AUTO_CONFIRM=1
            ;;
        --docker)
            DEPLOY_MODE="docker"
            ;;
        --native)
            DEPLOY_MODE="native"
            ;;
        --platform=*)
            PLATFORM_OVERRIDE="${_arg#*=}"
            ;;
        --dir=*)
            CUSTOM_DIR="${_arg#*=}"
            ;;
        --version=*|-v=*)
            CUSTOM_VER="${_arg#*=}"
            ;;
    esac
done

[ -z "$CUSTOM_VER" ] && CUSTOM_VER="${CUBEX_VERSION:-}"
REL_TAG="v9.992"

case "$PLATFORM_OVERRIDE" in
    fnos)
        run_platform_fnos
        ;;
    openwrt-docker|openwrt)
        run_platform_openwrt_docker
        ;;
    auto|linux|pve|"")
        run_platform_linux
        ;;
    *)
        msg "${RED}❌ 未知平台参数: $PLATFORM_OVERRIDE (支持 auto/linux/fnos/openwrt-docker)${NC}"
        exit 1
        ;;
esac
